{"command":"cat > src/cli.js <<'EOF'
const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'rounds' && mode !== 'tally') {
  process.stderr.write('error: usage: cli.js rounds|tally\n')
  process.exit(2)
}
import('node:fs').then(({ readFileSync }) => {
  let text = readFileSync(0, 'utf8')
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let cands = null
  const ballots = []
  const fail = (n, msg) => {
    process.stderr.write(n ? `error: line ${n}: ${msg}\n` : `error: ${msg}\n`)
    process.exit(2)
  }
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (cands !== null || ballots.length) fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 2) fail(n, 'expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(name)) fail(n, `invalid candidate name ${name}`)
        if (seen.has(name)) fail(n, `candidate ${name} is declared twice`)
        seen.add(name)
      }
      cands = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (cands === null) fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 3) fail(n, 'expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail(n, 'count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!cands.includes(name)) fail(n, `unknown candidate ${name}`)
        if (seen.has(name)) fail(n, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else {
      fail(n, `unknown directive ${t[0]}`)
    }
  }
  if (cands === null) fail(0, 'no candidates')

  const alive = new Set(cands)
  const history = []
  const out = []
  let winner = null
  let k = 0
  for (;;) {
    k++
    const counts = new Map([...alive].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const c = b.prefs.find((p) => alive.has(p))
      if (c !== undefined) {
        counts.set(c, counts.get(c) + b.count)
        active += b.count
      }
    }
    history.push(counts)
    const exhausted = ballots.reduce((s, b) => s + b.count, 0n) - active
    const order = [...alive].sort((a, b) => (counts.get(a) > counts.get(b) ? -1 : counts.get(a) < counts.get(b) ? 1 : a < b ? -1 : a > b ? 1 : 0))
    out.push(`round ${k}: ${order.map((c) => `${c}=${counts.get(c)}`).join(' ')} exhausted=${exhausted}`)
    if (active === 0n) break
    const top = order.find((c) => counts.get(c) * 2n > active)
    if (top !== undefined) { winner = top; break }
    let set = [...alive]
    const min0 = set.reduce((m, c) => (counts.get(c) < m ? counts.get(c) : m), counts.get(set[0]))
    set = set.filter((c) => counts.get(c) === min0)
    for (let r = 0; r < history.length && set.length > 1; r++) {
      const vals = set.map((c) => history[r].get(c))
      const m = vals.reduce((a, b) => (b < a ? b : a))
      if (vals.some((v) => v !== m)) set = set.filter((c) => history[r].get(c) === m)
    }
    const gone = set.reduce((a, b) => (b > a ? b : a))
    alive.delete(gone)
    out.push(`eliminated ${gone}`)
  }
  const end = winner === null ? 'no winner' : `winner ${winner}`
  process.stdout.write((mode === 'tally' ? `rounds ${k}\n` : out.join('\n') + '\n') + end + '\n')
})
EOF
node --test test/*.test.js 2>&1 | grep -E "^# (pass|fail)"","description":"Write CLI and run tests"}

